mapper.select:
SELECT LOG_ID AS logId, LOG_TYPE_CD AS logTypeCd, USER_ID AS userId, ACTION_CD AS actionCd, MESSAGE AS message, DETAIL_CONTENT AS detailContent, IP_ADDRESS AS ipAddress, CREATED_DT AS createdDt, USE_YN AS useYn FROM SYSTEM_LOG
USE_YN = 'Y'
AND LOG_TYPE_CD = #{logTypeCd}
AND USER_ID = #{userId}
AND ACTION_CD = #{actionCd}
AND MESSAGE LIKE '%' || #{keyword} || '%'
AND CREATED_DT >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND CREATED_DT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
ORDER BY CREATED_DT DESC, LOG_ID DESC
